select '4a617bee-8785-5fd7-86c1-4f92216926a6', l.id, 1,
  'La cytologie étudie la cellule', 'Cytology studies the cell', 'La cellule est l''unité structurale et fonctionnelle de base du vivant.', 'The cell is the basic structural and functional unit of life.', 'https://kjlgrgdryimazczrcvgx.supabase.co/storage/v1/object/public/lesson-media/biologie/cytologie-i/cellule.PNG', 'https://kjlgrgdryimazczrcvgx.supabase.co/storage/v1/object/public/lesson-media/biologie/cytologie-i/cellule.PNG',
  'La cytologie est la branche de la biologie qui étudie la cellule. La cellule est l''unité structurale et fonctionnelle de base de tous les êtres vivants : c''est la plus petite entité capable d''accomplir les fonctions de la vie (métabolisme, multiplication, échanges). Robert Hooke l''a observée pour la première fois en 1665 sur des coupes de liège.', 'Cytology is the branch of biology that studies the cell. The cell is the basic structural and functional unit of every living being: it is the smallest entity able to carry out the functions of life (metabolism, reproduction, exchanges). Robert Hooke first observed it in 1665 on slices of cork.', 'Quelle est l''unité de base du vivant ?', 'What is the basic unit of life?',
  'La cellule', 'The cell', 'La cellule est la première unité capable de vivre de façon autonome.', 'The cell is the first unit able to live on its own.', 'Un organite ou une molécule n''est pas vivant par lui-même.', 'An organelle or a molecule is not alive on its own.'
from public.lessons l join public.chapters ch on ch.id = l.chapter_id join public.subjects s on s.id = ch.subject_id
