select '64fa248f-cb95-5bb1-98ad-b0349f9255a8', l.id, 1,
  'La mosaïque fluide', 'The fluid mosaic', 'Une bicouche lipidique dans laquelle nagent des protéines.', 'A lipid bilayer in which proteins float.', 'https://kjlgrgdryimazczrcvgx.supabase.co/storage/v1/object/public/lesson-media/biologie/cytologie-i/Membrane.jpg', 'https://kjlgrgdryimazczrcvgx.supabase.co/storage/v1/object/public/lesson-media/biologie/cytologie-i/Membrane.jpg',
  'La membrane plasmique suit le modèle de la mosaïque fluide de Singer et Nicolson : une bicouche de phospholipides dans laquelle sont insérées des protéines intrinsèques (transmembranaires) et extrinsèques (périphériques). La membrane est fluide, asymétrique et dotée d''une perméabilité sélective.', 'The plasma membrane follows the Singer-Nicolson fluid mosaic model: a phospholipid bilayer with intrinsic (transmembrane) and extrinsic (peripheral) proteins embedded in it. The membrane is fluid, asymmetric and selectively permeable.', 'Quel modèle décrit la membrane plasmique ?', 'Which model describes the plasma membrane?',
  'Mosaïque fluide', 'Fluid mosaic', 'Imaginer une mer de lipides où flottent des icebergs de protéines.', 'Picture a sea of lipids with protein icebergs floating in it.', 'Le modèle en sandwich (protéines entre deux couches de lipides) est faux.', 'The sandwich model (proteins between two lipid layers) is wrong.'
from public.lessons l join public.chapters ch on ch.id = l.chapter_id join public.subjects s on s.id = ch.subject_id
