select '140dc6f9-5b29-5a61-81dd-bfe10ccc64b7', l.id, 2,
  'Composition : protéines majoritaires en masse', 'Composition: proteins dominate by mass', 'Protéines ~55 %, lipides 25-40 %, glucides 3-10 %.', 'Proteins ~55%, lipids 25-40%, carbohydrates 3-10%.', 'https://kjlgrgdryimazczrcvgx.supabase.co/storage/v1/object/public/lesson-media/biologie/cytologie-i/Membrane.jpg', 'https://kjlgrgdryimazczrcvgx.supabase.co/storage/v1/object/public/lesson-media/biologie/cytologie-i/Membrane.jpg',
  'En masse, la membrane contient environ 55 % de protéines, 25 à 40 % de lipides et seulement 3 à 10 % de glucides. Les glucides ne se trouvent que sur la face extracellulaire, où ils forment le glycocalyx, essentiel à la reconnaissance cellulaire. Les récepteurs membranaires sont de nature protéique.', 'By mass, the membrane contains about 55% proteins, 25-40% lipids and only 3-10% carbohydrates. Carbohydrates sit only on the extracellular face, where they form the glycocalyx, essential for cell recognition. Membrane receptors are protein in nature.', 'Composant majoritaire en masse de la membrane ?', 'Which component dominates the membrane by mass?',
  'Les protéines', 'Proteins', 'Les glucides sont exclusivement sur la face externe : le glycocalyx.', 'Carbohydrates are found only on the outer face: the glycocalyx.', 'On croit les lipides majoritaires ; en masse ce sont les protéines.', 'People think lipids dominate; by mass it is proteins.'
from public.lessons l join public.chapters ch on ch.id = l.chapter_id join public.subjects s on s.id = ch.subject_id
