select '12756e7d-4975-5131-ac3e-fd13aa49c037', l.id, 1,
  'La mitochondrie : centrale énergétique', 'The mitochondrion: the powerhouse', 'Organite semi-autonome qui produit l''ATP.', 'Semi-autonomous organelle that produces ATP.', 'https://kjlgrgdryimazczrcvgx.supabase.co/storage/v1/object/public/lesson-media/biologie/cytologie-i/Mito.jpg', 'https://kjlgrgdryimazczrcvgx.supabase.co/storage/v1/object/public/lesson-media/biologie/cytologie-i/Mito.jpg',
  'La mitochondrie est le siège de la respiration cellulaire et produit la majeure partie de l''ATP. Elle est semi-autonome : elle possède son propre ADN, ses propres ribosomes et se divise de façon indépendante. Elle présente une double membrane, la membrane interne formant des crêtes.', 'The mitochondrion is the site of cellular respiration and produces most of the ATP. It is semi-autonomous: it has its own DNA, its own ribosomes and divides independently. It has a double membrane, its inner membrane forming cristae.', 'Quel organite produit l''ATP ?', 'Which organelle produces ATP?',
  'La mitochondrie', 'The mitochondrion', 'Double membrane + ADN propre = semi-autonomie de la mitochondrie.', 'Double membrane + own DNA = semi-autonomy of the mitochondrion.', 'La mitochondrie synthétise l''ATP ; elle ne le décompose pas.', 'The mitochondrion makes ATP; it does not break it down.'
from public.lessons l join public.chapters ch on ch.id = l.chapter_id join public.subjects s on s.id = ch.subject_id
