select 'a87d2e2c-1b47-5dfa-979a-a974cf5a63ae', l.id, 3,
  'Résultat de la mitose : deux cellules filles 2n', 'Outcome of mitosis: two 2n daughter cells', 'Cytodiérèse puis deux cellules diploïdes identiques ; la méiose, elle, produit 4 cellules haploïdes.', 'Cytokinesis then two identical diploid cells; meiosis, by contrast, produces 4 haploid cells.', 'https://kjlgrgdryimazczrcvgx.supabase.co/storage/v1/object/public/lesson-media/biologie/division-cellulaire/Mitose.png', 'https://kjlgrgdryimazczrcvgx.supabase.co/storage/v1/object/public/lesson-media/biologie/division-cellulaire/Mitose.png',
  'Après la télophase, la cytodiérèse partage le cytoplasme : chez les animaux par étranglement de la membrane (anneau contractile d''actine et de myosine), chez les végétaux par formation d''une plaque cellulaire. La mitose est une division équationnelle : elle donne deux cellules filles diploïdes (2n), identiques entre elles et identiques à la cellule mère.', 'After telophase, cytokinesis shares the cytoplasm: in animals by membrane constriction (a contractile ring of actin and myosin), in plants by formation of a cell plate. Mitosis is an equational division: it produces two diploid daughter cells (2n), identical to each other and to the mother cell.', 'Nombre de cellules filles haploïdes produites par la méiose ?', 'How many haploid daughter cells does meiosis produce?',
  '4', '4', 'Mitose = 1 division équationnelle donnant 2 cellules 2n ; méiose = 2 divisions donnant 4 cellules n.', 'Mitosis = 1 equational division giving 2 cells 2n; meiosis = 2 divisions giving 4 cells n.', 'La mitose ne réduit jamais la ploïdie : elle conserve 2n. La réduction à n est le propre de la méiose.', 'Mitosis never reduces ploidy: it preserves 2n. The reduction to n is specific to meiosis.'
from public.lessons l join public.chapters ch on ch.id = l.chapter_id join public.subjects s on s.id = ch.subject_id
where s.slug = 'biologie' and ch.slug = 'division-cellulaire' and l.slug = 'la-mitose'
