select '5dc4aedc-d39e-5451-a340-4090e3569753', l.id, 3,
  'ADN vs ARN et fidélité de la réplication', 'DNA vs RNA and replication fidelity', 'A = T, C ≡ G, synthèse 5'' → 3'' ; la réplication précède la mitose, la transcription copie un gène.', 'A = T, C = G, 5'' to 3'' synthesis; replication precedes mitosis, transcription copies one gene.', 'https://kjlgrgdryimazczrcvgx.supabase.co/storage/v1/object/public/lesson-media/biologie/replication-adn/ADN-ARN.jpg', 'https://kjlgrgdryimazczrcvgx.supabase.co/storage/v1/object/public/lesson-media/biologie/replication-adn/ADN-ARN.jpg',
  'L''appariement des bases est complémentaire : A = T et C ≡ G. La réplication (ADN → ADN) précède toute division cellulaire et copie l''intégralité du génome en phase S ; la transcription (ADN → ARN) ne copie, dans le noyau, qu''un gène précis. L''ARN est monocaténaire et contient l''uracile (U) à la place de la thymine.', 'Base pairing is complementary: A = T and C = G. Replication (DNA to DNA) precedes any cell division and copies the whole genome during S phase; transcription (DNA to RNA) copies only one specific gene, in the nucleus. RNA is single-stranded and contains uracil (U) instead of thymine.', 'Base qui remplace la thymine dans l''ARN ?', 'Which base replaces thymine in RNA?',
  'Uracile', 'Uracil', 'Liaisons hydrogène entre les bases : deux pour A = T, trois pour C ≡ G.', 'Hydrogen bonds between bases: two for A = T, three for C = G.', 'La réplication copie tout le génome ; la transcription n''en copie qu''une portion (un gène). Ne confondez pas les deux processus.', 'Replication copies the whole genome; transcription copies only a portion (one gene). Do not confuse the two processes.'
from public.lessons l join public.chapters ch on ch.id = l.chapter_id join public.subjects s on s.id = ch.subject_id
where s.slug = 'biologie' and ch.slug = 'replication-adn' and l.slug = 'replication-adn'
