select '7dfce21b-bd67-5703-bcbe-5d885ee78e2c', l.id, 2,
  'L''ATP, monnaie énergétique universelle de la cellule', 'ATP, the universal energy currency of the cell', 'Hydrolyse ATP → ADP + Pi ; glucose à court terme, triglycérides à long terme.', 'Hydrolysis ATP → ADP + Pi; glucose short-term, triglycerides long-term.', null, null,
  'L''ATP est la monnaie énergétique universelle : elle sert de convertisseur entre les quatre formes d''énergie. Son hydrolyse (ATP → ADP + Pi) libère environ 30,5 kJ par mole en rompant une liaison phosphate. Le glucose fournit l''énergie rapidement mobilisable, tandis que les triglycérides constituent la réserve énergétique à long terme.', 'ATP is the universal energy currency: it acts as a converter between the four forms of energy. Its hydrolysis (ATP → ADP + Pi) releases about 30.5 kJ per mole by breaking a phosphate bond. Glucose provides rapidly mobilisable energy, while triglycerides form the long-term energy reserve.', 'Que libère l''hydrolyse de l''ATP ?', 'What does the hydrolysis of ATP release?',
  'ADP et Pi', 'ADP and Pi', 'ATP = pile rechargée, ADP = pile usée ; la phosphorylation (ADP + Pi) recharge la pile.', 'ATP = charged battery, ADP = spent battery; phosphorylation (ADP + Pi) recharges the battery.', 'Ne confondez pas ATP et glucose : l''ATP transporte l''énergie immédiate, le glucose est un stock mobilisable.', 'Do not confuse ATP and glucose: ATP carries immediate energy, glucose is a mobilisable store.'
from public.lessons l join public.chapters ch on ch.id = l.chapter_id join public.subjects s on s.id = ch.subject_id
